package com.hozefa.threepattipro.nativeapp;

import android.content.*;import android.os.*;
import com.google.firebase.FirebaseApp;import com.google.firebase.auth.*;import com.google.firebase.firestore.*;import com.google.android.gms.tasks.Tasks;
import okhttp3.*;import org.json.*;
import java.util.*;import java.util.concurrent.*;

/** One selected read-only score subscription. Never joins a room or changes presence. */
final class SessionLiveScores {
 interface Listener {void changed();void removed(String id);}
 private final Context context;private final Listener listener;private final String testEndpoint;private final Handler ui=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor(),connectionWorker=Executors.newSingleThreadExecutor();
 private final Handler connectionTimers=new Handler(Looper.getMainLooper());private Future<?> connectionTask;private volatile Call ticketCall;private WebSocket openingSocket;private long catalogLoadedAt;
 private final Runnable viewPause=this::pause;
 private final OkHttpClient http=new OkHttpClient.Builder().callTimeout(25,TimeUnit.SECONDS).pingInterval(20,TimeUnit.SECONDS).build();
 final Map<String,Map<String,Object>> boards=new LinkedHashMap<>();final Set<String> discoveredLive=new HashSet<>();
 private WebSocket socket;private ListenerRegistration legacy;private volatile int generation;private int failures;private volatile boolean foreground=true;private boolean opening,discovering;volatile boolean connected;volatile String selected="";String message="";JSONObject next;private volatile String owner="";
 SessionLiveScores(Context c,Listener l){this(c,l,null);}
 SessionLiveScores(Context c,Listener l,String endpoint){if(endpoint!=null&&!BuildConfig.USE_EMULATORS)throw new IllegalArgumentException("Test endpoint requires isolated build");context=c;listener=l;testEndpoint=endpoint;identity();}
 private FirebaseAuth auth(){return FirebaseAuth.getInstance(FirebaseApp.getInstance("three-patti-native"));}
 private String uid(){try{FirebaseUser u=auth().getCurrentUser();return u==null?"public":u.getUid();}catch(IllegalStateException absent){return "public";}}
 private String cacheKey(){return "session_boards_"+owner;}
 void identity(){String current=uid();if(current.equals(owner)&&!owner.isEmpty())return;disconnect();boards.clear();discoveredLive.clear();catalogLoadedAt=0;owner=current;if(!owner.isEmpty())try{JSONObject saved=new JSONObject(context.getSharedPreferences("preferences",0).getString(cacheKey(),"{}"));Iterator<String> keys=saved.keys();while(keys.hasNext()){String id=keys.next();boards.put(id,map(saved.getJSONObject(id)));}}catch(Exception invalid){boards.clear();}}
 private void persist(){if(owner.isEmpty())return;context.getSharedPreferences("preferences",0).edit().putString(cacheKey(),new JSONObject(boards).toString()).apply();}
 void forget(String id){boards.remove(id);discoveredLive.remove(id);persist();if(id.equals(selected))disconnect();}
 void discover(boolean more){identity();if(discovering||owner.isEmpty()||!foreground||!more&&catalogLoadedAt>0&&SystemClock.elapsedRealtime()-catalogLoadedAt<30000)return;discovering=true;String who=owner;JSONObject cursor=more?next:null;worker.execute(()->{try{JSONObject body=new JSONObject().put("operation","publicScoreboardRooms");if(cursor!=null)body.put("cursor",cursor);JSONObject reply=api(body);ui.post(()->{if(!foreground||!who.equals(uid()))return;if(!more)discoveredLive.clear();JSONArray rows=reply.optJSONArray("rooms");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i),score=row==null?null:row.optJSONObject("scoreboard");if(score==null)continue;Map<String,Object> value=map(score);String id=SessionLeaderboard.id(value);Map<String,Object> old=boards.get(id);if(old==null||AdvancedAnalytics.number(value.get("revision"))>=AdvancedAnalytics.number(old.get("revision")))boards.put(id,value);if(SessionLeaderboard.active(value))discoveredLive.add(id);}JSONArray removed=reply.optJSONArray("removed");if(removed!=null)for(int i=0;i<removed.length();i++){String gone=removed.optString(i);forget(gone);listener.removed(gone);}next=reply.optJSONObject("next");catalogLoadedAt=SystemClock.elapsedRealtime();persist();listener.changed();});}catch(Exception unavailable){/* Cached history remains available. No retry polling. */}finally{ui.post(()->discovering=false);}});}
 void select(Map<String,Object> session){identity();String id=session!=null&&SessionLeaderboard.id(session).startsWith("cf2_")?SessionLeaderboard.id(session):"";if(selected.equals(id))return;disconnect();selected=id;if(id.isEmpty()||!foreground)return;if(id.startsWith("cf2_"))connect();else attachLegacy(id);}
 private void attachLegacy(String id){final int gen=generation;legacy=FirebaseFirestore.getInstance(FirebaseApp.getInstance("three-patti-native")).document("onlineRooms/"+id).addSnapshotListener(MetadataChanges.INCLUDE,(snapshot,error)->{if(gen!=generation||!id.equals(selected)||!foreground)return;if(error!=null){connected=false;message="Live access unavailable · showing saved scores";listener.changed();return;}if(!snapshot.exists()){if(!snapshot.getMetadata().isFromCache()){forget(id);listener.removed(id);}return;}Map<String,Object> r=snapshot.getData();Map<String,Object> next=legacyBoard(id,r),prior=new HashMap<>(boards.getOrDefault(id,Collections.emptyMap())),comparison=new HashMap<>(next);prior.remove("revision");comparison.remove("revision");boolean liveNow=!snapshot.getMetadata().isFromCache()&&!snapshot.getMetadata().hasPendingWrites();if(prior.equals(comparison)&&connected==liveNow)return;boards.put(id,next);connected=liveNow;message=connected?"":"Saved session scores · reconnecting";persist();listener.changed();});}
 private void connect(){if(!foreground||selected.isEmpty()||opening)return;opening=true;final int gen=generation;final String id=selected,who=owner;connectionTask=connectionWorker.submit(()->{try{JSONObject ticket=api(new JSONObject().put("operation","publicScoreboardTicket").put("roomId",id),gen);if(!validConnection(gen,who,id))return;String endpoint=endpoint().replaceFirst("^https:","wss:").replaceFirst("^http:","ws:").replaceAll("kaliApi$","kaliSocket")+"?roomId="+id;WebSocket candidate=http.newWebSocket(new Request.Builder().url(endpoint).header("Sec-WebSocket-Protocol","kali.v2, ticket."+ticket.getString("ticket")).build(),new WebSocketListener(){
  @Override public void onOpen(WebSocket ws,Response response){ui.post(()->{if(gen!=generation||!foreground||!who.equals(uid())){ws.close(1000,"Changed");return;}WebSocket old=socket;socket=ws;opening=false;failures=0;if(old!=null)old.close(1000,"Renewed");connectionTimers.postDelayed(()->{if(gen==generation)connect();},240000);});}
  @Override public void onMessage(WebSocket ws,String text){try{JSONObject msg=new JSONObject(text);if("removed".equals(msg.optString("type"))&&id.equals(msg.optString("sessionId"))){ui.post(()->{if(gen==generation&&socket==ws&&who.equals(uid())){forget(id);listener.removed(id);}});return;}JSONObject score=msg.optJSONObject("scoreboard");if(score==null||!id.equals(score.optString("id")))return;Map<String,Object> value=map(score);ui.post(()->{if(gen!=generation||socket!=ws||!who.equals(uid()))return;Map<String,Object> old=boards.get(id);if(old!=null&&AdvancedAnalytics.number(value.get("revision"))<AdvancedAnalytics.number(old.get("revision")))return;boolean changed=!connected||!sameBoard(old,value)||!message.isEmpty();boards.put(id,value);connected=true;message="";if(changed){persist();listener.changed();}});}catch(JSONException ignored){}}
  @Override public void onClosing(WebSocket ws,int code,String reason){ws.close(code,reason);}
  @Override public void onClosed(WebSocket ws,int code,String reason){ui.post(()->{if(gen!=generation||socket!=ws)return;socket=null;connected=false;if(code==4004){forget(id);listener.removed(id);}else if(code==4003){message="Live access unavailable · showing saved scores";listener.changed();}else retry(gen);});}
  @Override public void onFailure(WebSocket ws,Throwable t,Response response){ui.post(()->{if(gen!=generation)return;opening=false;if(socket==ws)socket=null;if(socket==null){connected=false;retry(gen);}else connectionTimers.postDelayed(()->{if(gen==generation)connect();},5000);});}
 });synchronized(this){if(validConnection(gen,who,id))openingSocket=candidate;else candidate.cancel();}}catch(Exception error){ui.post(()->{if(gen!=generation)return;opening=false;if(String.valueOf(error.getMessage()).contains("Session was deleted")){forget(id);listener.removed(id);}else if(String.valueOf(error.getMessage()).contains("Not a room participant")||String.valueOf(error.getMessage()).contains("Sign in")){connected=false;message="Live access unavailable · showing saved history";listener.changed();}else if(socket==null){connected=false;message=error.getMessage();retry(gen);}});}});}
 private void retry(int gen){if(!foreground||selected.isEmpty())return;message="Saved session scores · reconnecting";listener.changed();connectionTimers.postDelayed(()->{if(gen==generation)connect();},Math.min(30000,1000L<<Math.min(failures++,5)));}
 private static boolean sameBoard(Map<String,Object> a,Map<String,Object> b){if(a==null)return false;Map<String,Object> left=new HashMap<>(a),right=new HashMap<>(b);left.remove("revision");right.remove("revision");return left.equals(right);}
 private boolean validConnection(int gen,String who,String id){return foreground&&generation==gen&&who.equals(uid())&&id.equals(selected);}
 private JSONObject api(JSONObject body)throws Exception{return api(body,-1);}
 private JSONObject api(JSONObject body,int gen)throws Exception{
  body.put("clientProtocol",2);String who=owner;
  if(gen>=0&&!validConnection(gen,who,body.optString("roomId")))throw new CancellationException("Session changed");
  // Public standings never create/change an Auth identity or request a token.
  Request req=new Request.Builder().url(endpoint()).post(RequestBody.create(body.toString(),MediaType.get("application/json"))).build();Call call=http.newCall(req);
  if(gen>=0)synchronized(this){if(!validConnection(gen,who,body.optString("roomId")))throw new CancellationException("Session changed");ticketCall=call;}
  try(Response res=call.execute()){JSONObject data=new JSONObject(res.body().string());if(!res.isSuccessful())throw new IllegalStateException(data.optString("error","Session connection unavailable"));return data;}
  finally{if(gen>=0)synchronized(this){if(ticketCall==call)ticketCall=null;}}
 }
 private String endpoint()throws Exception{if(testEndpoint!=null)return testEndpoint;if(BuildConfig.USE_EMULATORS)return "http://10.0.2.2:5001/demo-three-patti/asia-south1/kaliApi";try(java.io.Reader in=new java.io.InputStreamReader(context.getAssets().open("kali/config.js"),java.nio.charset.StandardCharsets.UTF_8)){StringBuilder s=new StringBuilder();char[] b=new char[1024];int n;while((n=in.read(b))!=-1)s.append(b,0,n);return OnlineEndpoint.api(s.toString());}}
 void pauseAfterDelay(){ui.removeCallbacks(viewPause);ui.postDelayed(viewPause,15000);}
 void pause(){ui.removeCallbacks(viewPause);foreground=false;catalogLoadedAt=0;disconnect();discoveredLive.clear();}
 void resume(){ui.removeCallbacks(viewPause);foreground=true;identity();}
 void disconnect(){synchronized(this){generation++;if(ticketCall!=null){ticketCall.cancel();ticketCall=null;}}connectionTimers.removeCallbacksAndMessages(null);if(connectionTask!=null){connectionTask.cancel(true);connectionTask=null;}if(openingSocket!=null){openingSocket.cancel();openingSocket=null;}if(socket!=null){socket.close(1000,"Score view closed");socket=null;}if(legacy!=null){legacy.remove();legacy=null;}connected=false;opening=false;selected="";message="";}
 void close(){pause();worker.shutdownNow();connectionWorker.shutdownNow();http.dispatcher().cancelAll();}
 static Map<String,Object> map(JSONObject json){Map<String,Object> out=new LinkedHashMap<>();Iterator<String> keys=json.keys();while(keys.hasNext()){String k=keys.next();out.put(k,value(json.opt(k)));}return out;}
 private static Object value(Object v){if(v==JSONObject.NULL)return null;if(v instanceof JSONObject)return map((JSONObject)v);if(v instanceof JSONArray){List<Object> list=new ArrayList<>();for(int i=0;i<((JSONArray)v).length();i++)list.add(value(((JSONArray)v).opt(i)));return list;}return v;}
 private static Map<String,Object> legacyBoard(String id,Map<String,Object> r){Map<String,Object> out=new HashMap<>();for(String key:Arrays.asList("sessionName","revision","status","completed"))out.put(key,r.get(key));out.put("id",id);out.put("roomId",id);out.put("source","online");out.put("startTime",r.get("startedAt")==null?r.get("createdAt"):r.get("startedAt"));out.put("endTime",r.get("endedAt"));out.put("totalRounds",r.get("completed"));out.put("pendingExports",0);out.put("paused",r.get("paused"));List<Map<String,Object>> rows=new ArrayList<>();Map<?,?> names=r.get("scoreNames") instanceof Map?(Map<?,?>)r.get("scoreNames"):Collections.emptyMap(),stats=r.get("stats") instanceof Map?(Map<?,?>)r.get("stats"):Collections.emptyMap(),totals=r.get("totals") instanceof Map?(Map<?,?>)r.get("totals"):Collections.emptyMap();for(Object key:totals.keySet()){Map<?,?> s=stats.get(key) instanceof Map?(Map<?,?>)stats.get(key):Collections.emptyMap();rows.add(SessionLeaderboard.FirebaseMap.of("id",String.valueOf(key),"name",names.get(key)==null?String.valueOf(key):names.get(key),"score",totals.get(key),"roundsPlayed",s.get("roundsPlayed"),"wins",s.get("wins"),"losses",s.get("losses"),"asHukum",s.get("asHukum"),"asPartner",s.get("asPartner")));}out.put("leaderboard",rows);return out;}
}
